import {describe, expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const provider: AIProvider = {
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'unexpected'};
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
};

describe('beforeSession failure', () => {
  it('calls onError with the session and error before cleanup', async () => {
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const error = new Error('setup failed');
    const calls: unknown[] = [];
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
      hooks: {
        beforeSession: async () => { throw error; },
        onError: async (receivedSession, receivedError) => { calls.push([receivedSession, receivedError]); },
        afterSession: async () => { calls.push('cleanup'); },
      },
    });
    const rejection = await orchestrator.processMessage(session).catch((caught: unknown) => caught);
    expect({rejection, calls}).toEqual({rejection: error, calls: [[session, error], 'cleanup']});
  });
});
EOF
